verifier_source:
# Standalone exact verifier, zero imports, no I/O, no print, no filesystem.
# Discipline: def verify(witness) raises on any failed check. Exact integer
# arithmetic only. Fail-closed: any anomaly raises. Clean return = PASS.

def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

def mpow_exact(b, e, m):
    r = 1
    b = b % m
    while e > 0:
        if e % 2 == 1:
            r = (r * b) % m
        b = (b * b) % m
        e //= 2
    return r

def prime_factors(n):
    fs = set()
    m = n
    d = 2
    while d * d <= m:
        while m % d == 0:
            fs.add(d)
            m //= d
        d += 1
    if m > 1:
        fs.add(m)
    return fs

def order_is_full(a, p):
    n = p - 1
    for f in prime_factors(n):
        if mpow_exact(a, n // f, p) == 1:
            return False
    return mpow_exact(a, n, p) == 1

def least_prime_primitive_root(p):
    for q in range(2, p):
        if is_prime(q) and order_is_full(q, p):
            return q
    raise RuntimeError('FAIL: no primitive root found')

def verify(witness):
    if not isinstance(witness, dict):
        raise RuntimeError('FAIL: witness not a dict')
    if witness.get('contract_sha') != '92de17cc91e715eb':
        raise RuntimeError('FAIL: contract sha mismatch')
    instances = witness.get('instances')
    if not isinstance(instances, list) or len(instances) == 0:
        raise RuntimeError('FAIL: no instances')
    for inst in instances:
        p = inst.get('p')
        expected = inst.get('least_prime_primitive_root')
        if not isinstance(p, int) or not isinstance(expected, int):
            raise RuntimeError('FAIL: non-integer instance')
        if not is_prime(p) or p <= 2:
            raise RuntimeError('FAIL: p not an admissible prime')
        if not is_prime(expected):
            raise RuntimeError('FAIL: claimed least primitive root not prime')
        if not order_is_full(expected, p):
            raise RuntimeError('FAIL: claimed least primitive root does not generate')
        for q in range(2, expected):
            if is_prime(q) and order_is_full(q, p):
                raise RuntimeError('FAIL: smaller prime generates')
        got = least_prime_primitive_root(p)
        if got != expected:
            raise RuntimeError('FAIL: independent recomputation disagrees')
    # clean return = PASS
